mapper.select:
select c.cus_award_id, c.activity_id, c.award_id, c.openid, c.get_state, c.award_from, c.customer_ip, a.award_name, c.created_date from cmwa_wx_act_customer_award c , cmwa_wx_act_award_info a where c.award_id = a.award_id and c.activity_id = #{map.activityId} and c.openid = #{map.openId} and a.award_state = 0
and c.award_id = #{map.awardId}
and c.get_state = #{map.getState}
and a.award_type = #{map.awardType}
and a.award_type != 2
and award_from = #{map.awardFrom}
and to_char(c.created_date,'dd')=to_char(SYSDATE,'dd')
and a.award_pid = ( select a1.award_id from cmwa_wx_act_award_info a1 where a1.award_name = #{map.boxState} )
order by a.award_sort

mapper.update:
UPDATE cmwa_wx_act_customer_award
   SET UPDATED_DATE = SYSDATE,
   	   GET_STATE=#{getState}
 WHERE CUS_AWARD_ID = #{cusAwardId}

mapper.select:
select t.get_state awardState, t1.award_price awardPrice, t1.invalid_date invalidDate, t1.award_id awardId, t.cus_award_id cusAwardId, t1.AWARD_NAME awardName, T2.store_id storeId, T2.AWARD_NUM awardNum from CMWA_WX_ACT_CUSTOMER_AWARD t,CMWA_WX_ACT_AWARD_STORE T2, (select t.award_id,t.AWARD_PRICE,t.INVALID_DATE,t.AWARD_NAME from cmwa_wx_act_award_info t where t.activity_id = #{param.activityId,jdbcType=VARCHAR}
and t.award_name like '%'||#{param.awardName,jdbcType=VARCHAR}||'%'
and t.AWARD_TYPE = #{param.awardType,jdbcType=VARCHAR}
) t1 where t.award_id = t1.award_id and t.openid = #{param.openid,jdbcType=VARCHAR} AND T.store_id = t2.store_id(+)

select 
  	count(1)
from 
  	cmwa_wx_act_customer_award c
where 
   	c.activity_id = #{map.activityId}
and 
	c.openid = #{map.openId}

	and c.award_id = #{map.awardId}


	and c.get_state = #{map.getState}


	and to_char(c.created_date,'yyyy-mm-dd')=to_char(SYSDATE,'yyyy-mm-dd')

select page.* from (select t.get_state "awardState", t1.award_price "awardPrice", t1.invalid_date "invalidDate", t.cus_award_id "cusAwardId", t1.award_id "awardId", t1.AWARD_NAME "awardName", t.openid "openid", rownum rw from CMWA_WX_ACT_CUSTOMER_AWARD t , (select t.award_id,t.AWARD_PRICE,t.INVALID_DATE,t.AWARD_NAME from cmwa_wx_act_award_info t where t.activity_id = #{param.activityId,jdbcType=VARCHAR}
and t.award_name like '%'||#{param.awardName,jdbcType=VARCHAR}||'%'
and t.AWARD_TYPE = #{param.awardType,jdbcType=VARCHAR}
) t1 where t.award_id = t1.award_id and sysdate < t1.invalid_date
and t.openid in(
#{str}
order by t.created_date desc) page where page.rw<10

		select t4.award_name  "awardName", t4.nickname "nickname",t4.created_date "createdDate"
         from (select t2.award_name,
                      t3.nickname,
                      to_char(t1.created_date,'YYYY-MM-DD HH24:MI:SS') as created_date,
                      rownum rw
                 from cmwa_wx_act_customer_award t1,
                      cmwa_wx_act_award_info     t2,
                      cmwa_wx_user_info          t3
                where t1.award_id = t2.award_id

					   and t2.award_type = #{param.awardType,jdbcType=VARCHAR}

                  and t1.activity_id = #{param.activityId,jdbcType=VARCHAR}
                  and t1.openid = t3.openid
                  and rownum <=#{param.endIdx,jdbcType=VARCHAR}
                order by t1.created_date desc) t4 where t4.rw >= #{param.beginIdx,jdbcType=VARCHAR}

select count(1)
  from cmwa_wx_act_customer_award t1,
       cmwa_wx_act_award_info     t2,
       cmwa_wx_user_info          t3
 where t1.award_id = t2.award_id

	   and t2.award_type = #{param.awardType,jdbcType=VARCHAR}

   and t1.activity_id = #{param.activityId,jdbcType=VARCHAR}
   and t1.openid = t3.openid
 order by t1.created_date desc

select count(1)
 from cmwa_wx_act_customer_award t1
where t1.activity_id = #{param.activityId,jdbcType=VARCHAR}
